// patches/part28_5_dashboard_login.mjs  (run from repo root: node patches/part28_5_dashboard_login.mjs [--dry] [--force])
// P28 Part 5 (ADR 0056). Needs part28_1 to _4b (and part28_4a_fix_ruff) applied first. Dashboard only; the host is not touched.
// New: the name and PIN login screen (default) with "Remember me on this browser" (off) and a link to the admin token form; the host's session token is kept in the same slot as the
//   operator token, in sessionStorage or, with the box ticked, localStorage; Log out in the top strip (asks once; POST /api/logout, then clears both storages and shows Login, also when the host is down);
//   close code 4401 and a 401 on any logged-in REST call clear both storages and show Login.
// New files: dashboard/src/store/token.ts, dashboard/src/api/authfetch.ts, dashboard/tests/login_pin.test.ts, dashboard/tests/login_ui.test.tsx.
// Edited: api/login.ts, store/controller.ts, store/live.ts, store/actions.ts, app/runtime.ts, components/LoginPage.tsx, Shell.tsx, TopStrip.tsx, SystemBanners.tsx, tests/shell.test.tsx, tests/watchdog_ui.test.tsx,
//   e2e/tests/helpers.ts (opens the admin token form), docs/adr/0056.md, docs/PROGRESS.md. The frozen design docx is not touched.
// Not here: the Playwright PIN test with a mock-host PIN login, the doctor row and the README note (P28-6).
// Safe to run twice. CRLF files keep their CRLF. --dry writes nothing.
import fs from 'node:fs';
import path from 'node:path';
const ROOT = process.cwd(), DRY = process.argv.includes('--dry'), FORCE = process.argv.includes('--force');
const abs = (p) => path.join(ROOT, p), plan = [];
const put = (p, content, replaces) => plan.push({ op: 'put', p, content, replaces });
const replace = (p, o, n) => plan.push({ op: 'replace', p, o, n });
const append = (p, text) => plan.push({ op: 'append', p, text });
const eolOf = (s) => (s.includes('\r\n') ? '\r\n' : '\n');
const toEol = (t, e) => t.replace(/\r\n/g, '\n').replace(/\n/g, e);
const lf = (s) => s.replace(/\r\n/g, '\n');
function apply() {
  const state = new Map(), log = [];
  const get = (p) => (state.has(p) ? state.get(p) : fs.existsSync(abs(p)) ? fs.readFileSync(abs(p), 'utf8') : null);
  for (const s of plan) {
    const cur = get(s.p);
    if (s.op === 'put') {
      const same = cur !== null && lf(cur) === lf(s.content), known = cur !== null && s.replaces && cur.includes(s.replaces);
      if (cur !== null && !same && !known && !FORCE) throw new Error(`EXISTS (use --force): ${s.p}`);
      log.push(`${cur === null ? 'create   ' : same ? 'unchanged' : 'overwrite'} ${s.p}`);
      if (!same) state.set(s.p, cur !== null && cur.includes('\r\n') ? toEol(s.content, '\r\n') : s.content);
    } else if (cur === null) throw new Error(`MISSING file: ${s.p} (run the earlier parts first, and run from the repo root)`);
    else if (s.op === 'replace') {
      const e = eolOf(cur), o = toEol(s.o, e), n = toEol(s.n, e), c = cur.split(o).length - 1;
      if (cur.includes(n)) log.push(`skip      ${s.p} (already applied)`);
      else if (c === 1) { state.set(s.p, cur.replace(o, () => n)); log.push(`edit      ${s.p}`); }
      else throw new Error(`ANCHOR found ${c} times in ${s.p}: ${s.o.slice(0, 70)}`);
    } else if (s.op === 'append') {
      const e = eolOf(cur), t = toEol(s.text, e);
      if (cur.includes(t.trim())) log.push(`skip      ${s.p} (already appended)`);
      else { state.set(s.p, cur + (cur.endsWith('\n') ? '' : e) + t + e); log.push(`append    ${s.p}`); }
    }
  }
  if (!DRY) for (const [p, c] of state) { fs.mkdirSync(path.dirname(abs(p)), { recursive: true }); fs.writeFileSync(abs(p), c); }
  console.log(log.join('\n') + (DRY ? '\n(dry run: nothing written)' : '\ndone'));
}

put("dashboard/src/api/authfetch.ts", "// fetch for every logged-in call (P28-5, ADR 0056). A 401 from the host on an /api call means the stored token or session is no longer\n// good: a login session that expired or was ended by Log out, a new PIN, rotate-token or disable-operator. The page is told once and\n// shows Login, the same as for close code 4401 on the sockets. The login call itself does not use this, because its 401 means a wrong name, PIN or token.\nlet lost: (() => void) | null = null;\n\nexport function onAuthLost(fn: (() => void) | null): void { lost = fn; }\n\nexport function authFetch(...a: Parameters<typeof fetch>): ReturnType<typeof fetch> {\n  return fetch(...a).then((res) => {\n    if (res.status === 401 && lost) lost();\n    return res;\n  });\n}\n");
put("dashboard/src/store/token.ts", "// Where the dashboard keeps its login token (ADR 0056, P28-5). There is one token slot with two possible homes: sessionStorage\n// (the default: gone when the tab closes) or localStorage (a PIN login with \"remember me\" ticked). A page that has no\n// window or a browser that blocks storage simply finds no token.\nimport { TOKEN_KEY } from './controller.ts';\n\nfunction areas(): Storage[] {\n  const out: Storage[] = [];\n  for (const get of [() => window.sessionStorage, () => window.localStorage]) {\n    try { out.push(get()); } catch { /* storage blocked by the browser */ }\n  }\n  return out;\n}\n\n// The stored token, from sessionStorage first and then localStorage; null when there is none.\nexport function readToken(): string | null {\n  for (const a of areas()) {\n    try { const v = a.getItem(TOKEN_KEY); if (v) return v; } catch { /* unreadable: try the next one */ }\n  }\n  return null;\n}\n\n// Removes the token from both places (log out, 4401, a 401 from the host).\nexport function clearToken(): void {\n  for (const a of areas()) {\n    try { a.removeItem(TOKEN_KEY); } catch { /* nothing more to do */ }\n  }\n}\n");
put("dashboard/tests/login_pin.test.ts", "// @vitest-environment jsdom\n// Requirements: REQ-SEC-003\n// P28-5 (ADR 0056): the PIN form of the login call, the logout call, the one token slot with two homes, and the 401 hook.\nimport { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';\nimport { postPinLogin, postLogout, postLogin } from '../src/api/login.ts';\nimport { authFetch, onAuthLost } from '../src/api/authfetch.ts';\nimport { createController, TOKEN_KEY } from '../src/store/controller.ts';\nimport { readToken, clearToken } from '../src/store/token.ts';\nimport { initialState, type LiveState } from '../src/store/reducer.ts';\nimport { FakeWs, FakeTimers, snapshot } from './helpers.ts';\n\nconst reply = (status: number, body: unknown) => vi.fn(async () => ({ status, json: async () => body })) as unknown as typeof fetch & ReturnType<typeof vi.fn>;\nconst sentBody = (f: ReturnType<typeof vi.fn>) => JSON.parse((f.mock.calls[0][1] as RequestInit).body as string);\nconst GOOD = { operator_id: 2, display_name: 'Ana', session_id: 4, session_token: 'sess-abc', expires_ts: 99 };\n\ndescribe('postPinLogin', () => {\n  it('sends display_name, pin and remember, and no token field', async () => {\n    const f = reply(200, GOOD);\n    await postPinLogin('Ana', '123456', true, f);\n    expect(sentBody(f as never)).toEqual({ display_name: 'Ana', pin: '123456', remember: true });\n  });\n  it('200 gives the operator and the session token', async () => {\n    expect(await postPinLogin('Ana', '123456', false, reply(200, GOOD))).toEqual({ kind: 'ok', operatorId: 2, displayName: 'Ana', sessionId: 4, sessionToken: 'sess-abc' });\n  });\n  it('a 200 without a session token is an error, not a login', async () => {\n    expect(await postPinLogin('Ana', '123456', false, reply(200, { operator_id: 2, display_name: 'Ana', session_id: 4 }))).toEqual({ kind: 'error', status: 200 });\n  });\n  it('401 carries retry_after_s, also the long wait of a locked operator', async () => {\n    expect(await postPinLogin('Ana', '000000', false, reply(401, { error_code: 'UNAUTHENTICATED', detail: 'x', retry_after_s: 900 }))).toEqual({ kind: 'rejected', retryAfterS: 900 });\n  });\n  it('the token form still sends only the token and returns no session token', async () => {\n    const f = reply(200, { operator_id: 1, display_name: 'Ana', session_id: 4 });\n    const r = await postLogin('tok', f);\n    expect(sentBody(f as never)).toEqual({ token: 'tok' });\n    expect(r).not.toHaveProperty('sessionToken');\n  });\n});\n\ndescribe('postLogout', () => {\n  it('posts to /api/logout with the bearer token', async () => {\n    const f = reply(200, { logged_out: true });\n    expect(await postLogout('sess-abc', f)).toBe(true);\n    const [url, init] = (f as unknown as ReturnType<typeof vi.fn>).mock.calls[0] as [string, RequestInit];\n    expect(url).toBe('/api/logout');\n    expect(init.method).toBe('POST');\n    expect((init.headers as Record<string, string>).Authorization).toBe('Bearer sess-abc');\n  });\n  it('a host that is down gives false and no exception', async () => {\n    expect(await postLogout('t', (async () => { throw new TypeError('down'); }) as unknown as typeof fetch)).toBe(false);\n  });\n});\n\ndescribe('authFetch (a 401 on a logged-in call means Login)', () => {\n  afterEach(() => { onAuthLost(null); vi.unstubAllGlobals(); });\n  const withStatus = (status: number) => vi.stubGlobal('fetch', vi.fn(async () => ({ status })));\n  it('calls the listener on 401 and still returns the response', async () => {\n    const lost = vi.fn(); onAuthLost(lost); withStatus(401);\n    expect((await authFetch('/api/events')).status).toBe(401);\n    expect(lost).toHaveBeenCalledTimes(1);\n  });\n  it('does not call it on 200, 403 or 409', async () => {\n    const lost = vi.fn(); onAuthLost(lost);\n    for (const s of [200, 403, 409]) { withStatus(s); await authFetch('/api/events'); }\n    expect(lost).not.toHaveBeenCalled();\n  });\n});\n\nfunction rig(opts: { session?: string; local?: string; blockLocalWrite?: boolean } = {}) {\n  const mk = (init?: string, blockWrite = false) => {\n    const m = new Map<string, string>(init ? [[TOKEN_KEY, init]] : []);\n    return { m, s: { getItem: (k: string) => m.get(k) ?? null, setItem: (k: string, v: string) => { if (blockWrite) throw new Error('full'); m.set(k, v); }, removeItem: (k: string) => void m.delete(k) } };\n  };\n  const ses = mk(opts.session), loc = mk(opts.local, opts.blockLocalWrite);\n  let st: LiveState = initialState('CONNECTING');\n  const sockets: FakeWs[] = [];\n  const c = createController({ store: { getState: () => st, setState: (n) => { st = n; } }, storage: ses.s, persistent: loc.s, url: 'ws://x/ws',\n    socketOptions: { timers: new FakeTimers(), create: () => { const w = new FakeWs(); sockets.push(w); return w; } } });\n  return { c, ses: ses.m, loc: loc.m, sockets, get: () => st };\n}\n\ndescribe('controller: remember me', () => {\n  it('login without remember keeps the token in sessionStorage only', () => {\n    const r = rig(); r.c.login('s1', false);\n    expect(r.ses.get(TOKEN_KEY)).toBe('s1'); expect(r.loc.has(TOKEN_KEY)).toBe(false);\n  });\n  it('login with remember keeps it in localStorage only, and the socket still sends it', () => {\n    const r = rig(); r.c.login('s1', true);\n    expect(r.loc.get(TOKEN_KEY)).toBe('s1'); expect(r.ses.has(TOKEN_KEY)).toBe(false);\n    r.sockets[0].open();\n    expect(JSON.parse(r.sockets[0].sent[0]).token).toBe('s1');\n  });\n  it('a remembered token starts the socket on a fresh tab (nothing in sessionStorage)', () => {\n    const r = rig({ local: 's1' }); r.c.start();\n    expect(r.sockets).toHaveLength(1);\n  });\n  it('blocked or full localStorage falls back to this tab only', () => {\n    const r = rig({ blockLocalWrite: true }); r.c.login('s1', true);\n    expect(r.ses.get(TOKEN_KEY)).toBe('s1');\n  });\n  it('a new login moves the token: remembered, then not remembered leaves nothing in localStorage', () => {\n    const r = rig(); r.c.login('s1', true); r.c.login('s2', false);\n    expect(r.loc.has(TOKEN_KEY)).toBe(false); expect(r.ses.get(TOKEN_KEY)).toBe('s2');\n  });\n  it('close 4401 clears both storages and shows Login', () => {\n    const r = rig({ local: 's1' }); r.c.start(); r.sockets[0].open(); r.sockets[0].push(snapshot()); r.sockets[0].drop(4401);\n    expect(r.loc.has(TOKEN_KEY)).toBe(false); expect(r.ses.has(TOKEN_KEY)).toBe(false); expect(r.get().conn).toBe('LOGIN');\n  });\n  it('logout clears both storages, closes the socket and shows Login', () => {\n    const r = rig({ session: 'a', local: 'b' }); r.c.start(); r.sockets[0].open(); r.c.logout();\n    expect(r.loc.has(TOKEN_KEY)).toBe(false); expect(r.ses.has(TOKEN_KEY)).toBe(false);\n    expect(r.sockets[0].closed).toBe(1000); expect(r.get().conn).toBe('LOGIN');\n  });\n  it('expire (a 401 from REST) does the same as logout without any host call', () => {\n    const r = rig({ local: 's1' }); r.c.start(); r.sockets[0].open(); r.sockets[0].push(snapshot()); r.c.expire();\n    expect(r.loc.has(TOKEN_KEY)).toBe(false); expect(r.get().conn).toBe('LOGIN'); expect(Object.keys(r.get().nodes)).toHaveLength(0);\n  });\n});\n\ndescribe('readToken and clearToken', () => {\n  beforeEach(() => { window.sessionStorage.clear(); window.localStorage.clear(); });\n  it('reads sessionStorage first, then localStorage, and null when empty', () => {\n    expect(readToken()).toBeNull();\n    window.localStorage.setItem(TOKEN_KEY, 'remembered'); expect(readToken()).toBe('remembered');\n    window.sessionStorage.setItem(TOKEN_KEY, 'tab'); expect(readToken()).toBe('tab');\n  });\n  it('clearToken empties both', () => {\n    window.sessionStorage.setItem(TOKEN_KEY, 'a'); window.localStorage.setItem(TOKEN_KEY, 'b');\n    clearToken(); expect(readToken()).toBeNull();\n  });\n});\n");
put("dashboard/tests/login_ui.test.tsx", "// @vitest-environment jsdom\n// Requirements: REQ-SEC-003\n// P28-5 (ADR 0056): the name and PIN login screen, the remember box, the admin token link, and Log out.\nimport { describe, it, expect, vi, afterEach, beforeEach } from 'vitest';\nimport { render, screen, fireEvent, cleanup } from '@testing-library/react';\nimport Shell from '../src/components/Shell.tsx';\nimport { liveStore } from '../src/store/live.ts';\nimport { initialState, apply } from '../src/store/reducer.ts';\nimport type { ServerMessage } from '../src/gen/ws.ts';\nimport { TOKEN_KEY } from '../src/store/controller.ts';\nimport { snapshot } from './helpers.ts';\n\nconst deps = () => ({ controller: { start: vi.fn(), login: vi.fn(), logout: vi.fn() }, bridge: { init: vi.fn() } });\nconst reply = (status: number, body: unknown) => vi.fn(async () => ({ status, json: async () => body })) as unknown as typeof fetch & ReturnType<typeof vi.fn>;\nconst GOOD = { operator_id: 2, display_name: 'Ana', session_id: 4, session_token: 'sess-abc', expires_ts: 99 };\nconst fill = (name: string, pin: string) => {\n  fireEvent.change(screen.getByLabelText('Name'), { target: { value: name } });\n  fireEvent.change(screen.getByLabelText('PIN'), { target: { value: pin } });\n};\nconst signIn = () => fireEvent.click(screen.getByRole('button', { name: 'Sign in' }));\nconst signInBtn = () => screen.getByRole('button', { name: 'Sign in' }) as HTMLButtonElement;\n\nbeforeEach(() => { window.sessionStorage.clear(); window.localStorage.clear(); liveStore.setState(initialState('LOGIN')); });\nafterEach(() => { cleanup(); vi.useRealTimers(); });\n\ndescribe('Login page, name and PIN', () => {\n  it('Sign in stays off until there is a name and a PIN of 6 to 12 digits', () => {\n    render(<Shell {...deps()} />);\n    expect(signInBtn().disabled).toBe(true);\n    fill('Ana', '12345'); expect(signInBtn().disabled).toBe(true);\n    fill('Ana', '12345a'); expect(signInBtn().disabled).toBe(true);\n    fill('Ana', '1234567890123'); expect(signInBtn().disabled).toBe(true);\n    fill('', '123456'); expect(signInBtn().disabled).toBe(true);\n    fill('Ana', '123456'); expect(signInBtn().disabled).toBe(false);\n    fill('Ana', '123456789012'); expect(signInBtn().disabled).toBe(false);\n  });\n  it('the PIN field hides what is typed, and Remember me is off by default', () => {\n    render(<Shell {...deps()} />);\n    expect((screen.getByLabelText('PIN') as HTMLInputElement).type).toBe('password');\n    expect((screen.getByLabelText(/Remember me/) as HTMLInputElement).checked).toBe(false);\n  });\n  it('a good login sends the PIN form, starts the socket with the session token and passes INIT_AUTH once', async () => {\n    const d = deps(), f = reply(200, GOOD);\n    render(<Shell {...d} fetchFn={f} />);\n    fill(' Ana ', '123456'); signIn();\n    await vi.waitFor(() => expect(d.controller.login).toHaveBeenCalledWith('sess-abc', false));\n    expect(d.bridge.init).toHaveBeenCalledWith('sess-abc');\n    expect(JSON.parse(((f as unknown as ReturnType<typeof vi.fn>).mock.calls[0][1] as RequestInit).body as string)).toEqual({ display_name: 'Ana', pin: '123456', remember: false });\n  });\n  it('with Remember me ticked the login says so to the host and to the controller', async () => {\n    const d = deps(), f = reply(200, GOOD);\n    render(<Shell {...d} fetchFn={f} />);\n    fill('Ana', '123456'); fireEvent.click(screen.getByLabelText(/Remember me/)); signIn();\n    await vi.waitFor(() => expect(d.controller.login).toHaveBeenCalledWith('sess-abc', true));\n    expect(JSON.parse(((f as unknown as ReturnType<typeof vi.fn>).mock.calls[0][1] as RequestInit).body as string).remember).toBe(true);\n  });\n  it('a wrong PIN shows the delay, starts nothing, and empties the PIN field', async () => {\n    const d = deps();\n    render(<Shell {...d} fetchFn={reply(401, { error_code: 'UNAUTHENTICATED', detail: 'invalid name or PIN', retry_after_s: 2 })} />);\n    fill('Ana', '000000'); signIn();\n    await screen.findByText(/Name or PIN not accepted\\. Wait 2 s/);\n    expect((screen.getByLabelText('PIN') as HTMLInputElement).value).toBe('');\n    expect(d.controller.login).not.toHaveBeenCalled(); expect(d.bridge.init).not.toHaveBeenCalled();\n  });\n  it('a locked operator is told the minutes and pointed to the admin token', async () => {\n    render(<Shell {...deps()} fetchFn={reply(401, { error_code: 'UNAUTHENTICATED', detail: 'x', retry_after_s: 840 })} />);\n    fill('Ana', '000000'); signIn();\n    await screen.findByText(/Too many wrong PINs\\. Try again in 14 min, or sign in with the admin token\\./);\n  });\n  it('an origin refusal and a host that is down have their own words', async () => {\n    const { unmount } = render(<Shell {...deps()} fetchFn={reply(403, {})} />);\n    fill('Ana', '123456'); signIn(); await screen.findByText(/refused this page address/);\n    unmount(); cleanup();\n    render(<Shell {...deps()} fetchFn={(async () => { throw new TypeError('x'); }) as unknown as typeof fetch} />);\n    fill('Ana', '123456'); signIn(); await screen.findByText('Host not reachable.');\n  });\n  it('the admin token link switches to the token form and back, and clears the message', async () => {\n    render(<Shell {...deps()} fetchFn={reply(401, { error_code: 'UNAUTHENTICATED', detail: 'x', retry_after_s: null })} />);\n    fill('Ana', '123456'); signIn(); await screen.findByText('Name or PIN not accepted.');\n    fireEvent.click(screen.getByRole('button', { name: 'Use the admin token instead' }));\n    expect(screen.queryByText('Name or PIN not accepted.')).toBeNull();\n    expect(screen.queryByLabelText('Token')).not.toBeNull(); expect(screen.queryByLabelText('PIN')).toBeNull();\n    fireEvent.click(screen.getByRole('button', { name: 'Sign in with name and PIN' }));\n    expect(screen.queryByLabelText('PIN')).not.toBeNull();\n  });\n});\n\ndescribe('Log out', () => {\n  const live = () => liveStore.setState(apply(initialState('CONNECTING'), snapshot() as unknown as ServerMessage).state);\n  // The live screen makes calls of its own (event log, banners): answer them quietly and keep every call for the asserts.\n  const host = (down = false) => {\n    const calls: { url: string; init: RequestInit }[] = [];\n    const fetchFn = (async (url: string, init: RequestInit) => {\n      calls.push({ url, init });\n      if (down && url === '/api/logout') throw new TypeError('down');\n      return { status: 200, json: async () => (url === '/api/logout' ? { logged_out: true } : { events: [], last_seq: 0 }) };\n    }) as unknown as typeof fetch;\n    return { calls, fetchFn, logout: () => calls.filter((c) => c.url === '/api/logout') };\n  };\n  it('shows no Log out button when the controller has no logout', () => {\n    live(); render(<Shell controller={{ start: vi.fn(), login: vi.fn() }} bridge={{ init: vi.fn() }} />);\n    expect(screen.queryByRole('button', { name: 'Log out' })).toBeNull();\n  });\n  it('asks once, and Cancel changes nothing', () => {\n    live(); const d = deps(), h = host();\n    render(<Shell {...d} fetchFn={h.fetchFn} />);\n    fireEvent.click(screen.getByRole('button', { name: 'Log out' }));\n    expect(screen.queryByText('This screen stops monitoring.')).not.toBeNull();\n    fireEvent.click(screen.getByRole('button', { name: 'Cancel' }));\n    expect(screen.queryByRole('button', { name: 'Log out' })).not.toBeNull();\n    expect(d.controller.logout).not.toHaveBeenCalled(); expect(h.logout()).toHaveLength(0);\n  });\n  it('confirming ends the session on the host with the stored token, then clears this page', async () => {\n    live(); window.sessionStorage.setItem(TOKEN_KEY, 'sess-abc');\n    const d = deps(), h = host();\n    render(<Shell {...d} fetchFn={h.fetchFn} />);\n    fireEvent.click(screen.getByRole('button', { name: 'Log out' }));\n    fireEvent.click(screen.getByRole('button', { name: 'Yes, log out' }));\n    await vi.waitFor(() => expect(d.controller.logout).toHaveBeenCalledTimes(1));\n    expect(h.logout()).toHaveLength(1);\n    expect(h.logout()[0].init.method).toBe('POST');\n    expect((h.logout()[0].init.headers as Record<string, string>).Authorization).toBe('Bearer sess-abc');\n  });\n  it('logs out on this page even when the host is down', async () => {\n    live(); window.localStorage.setItem(TOKEN_KEY, 'remembered');\n    const d = deps(), h = host(true);\n    render(<Shell {...d} fetchFn={h.fetchFn} />);\n    fireEvent.click(screen.getByRole('button', { name: 'Log out' }));\n    fireEvent.click(screen.getByRole('button', { name: 'Yes, log out' }));\n    await vi.waitFor(() => expect(d.controller.logout).toHaveBeenCalledTimes(1));\n    expect(h.logout()).toHaveLength(1); // it tried\n  });\n});\n");
replace("dashboard/src/api/login.ts",
  "// POST /api/login (design 3.8). The host waits out the failed-login delay before it answers 401,\n// so the page only shows retry_after_s; it does not time the delay itself.\nexport type LoginResult =\n  | { kind: 'ok'; operatorId: number; displayName: string; sessionId: number }\n  | { kind: 'rejected'; retryAfterS: number | null }\n  | { kind: 'origin' }",
  "// POST /api/login and POST /api/logout (design 3.8, ADR 0056). The host waits out the failed-login delay before it answers 401,\n// so the page only shows retry_after_s; it does not time the delay itself. A locked operator gets an immediate 401 whose\n// retry_after_s is the seconds left, which can be up to 900.\nexport type LoginResult =\n  | { kind: 'ok'; operatorId: number; displayName: string; sessionId: number; sessionToken?: string } // sessionToken: the PIN form only\n  | { kind: 'rejected'; retryAfterS: number | null }\n  | { kind: 'origin' }");
replace("dashboard/src/api/login.ts",
  "  | { kind: 'error'; status: number };\n\nexport async function postLogin(token: string, fetchFn: typeof fetch = fetch): Promise<LoginResult> {\n  let res: Response;\n  try {",
  "  | { kind: 'error'; status: number };\n\nasync function send(body: Record<string, unknown>, fetchFn: typeof fetch): Promise<LoginResult> {\n  let res: Response;\n  try {");
